"""Typed model elements: named types, module signatures, and expressions.

Types mirror the declaration vocabulary of the campaign language and are built
once per campaign by :func:`parse_types`.  Aliases are transparent for values
and layouts but keep their declaration name.

Expression nodes form the predicate AST.  Each node knows how to evaluate
itself against a lexical assignment dictionary, which keeps scoping (``all``
binding shadowing) local to the node that introduces it.
"""

from typing import Any, Dict, List, Optional, Tuple

import eywa.regex as regex


# --------------------------------------------------------------------------- #
# Types
# --------------------------------------------------------------------------- #

class Type(object):
    """An Eywa type for a parameter to a function."""

    __slots__ = ()

    @staticmethod
    def inner(type):
        """Look past any type aliases to get the inner type."""
        while isinstance(type, Alias):
            type = type.type
        return type


class Void(Type):
    """A void type representing no value."""

    __slots__ = ()


class Bool(Type):
    """A boolean type representing true or false."""

    __slots__ = ()


class Char(Type):
    """A character type representing a single Latin-1 character."""

    __slots__ = ()


class Int(Type):
    """An unsigned integer type of a given bit width."""

    __slots__ = ("size", "bytes", "limit")

    def __init__(self, size: int = 32):
        self.size = size                      # declared bits, 1..64
        self.bytes = _int_bytes(size)         # harness byte width
        self.limit = 1 << size                # exclusive value bound


def _int_bytes(bits: int) -> int:
    for width in (1, 2, 4, 8):
        if bits <= width * 8:
            return width
    return 8


class String(Type):
    """A bounded Latin-1 C string type."""

    __slots__ = ("maxsize", "char_type")

    def __init__(self, maxsize: int = 6):
        if maxsize < 0:
            raise Exception("invalid string type")
        self.maxsize = maxsize
        self.char_type = Char()


class Enum(Type):
    """An enumeration type representing a choice of values."""

    __slots__ = ("name", "values")

    def __init__(self, name: str, values: List[str]):
        self.name = name
        self.values = tuple(values)


class Array(Type):
    """An ordered fixed-length list of a given element type."""

    __slots__ = ("element_type", "maxsize")

    def __init__(self, element_type: Type, maxsize: int):
        self.maxsize = maxsize
        self.element_type = element_type


class Struct(Type):
    """An object with exactly the declared fields, in declaration order."""

    __slots__ = ("name", "fields", "names")

    def __init__(self, name: str, fields: Dict[str, Type]):
        self.name = name
        self.fields = fields                  # ordered field_name -> Type
        self.names = tuple(fields)


class Alias(Type):
    """A transparent value/layout alias that retains its declaration name."""

    __slots__ = ("name", "type", "description")

    def __init__(self, name: str, type: Type, description=None):
        self.name = name
        self.type = type
        self.description = description


_PRIMITIVES = (Void(), Bool(), Char())


def parse_types(defs) -> Dict[str, Type]:
    """Build the named type registry, resolving forward references."""
    types: Dict[str, Type] = {}
    deferred: List[Tuple[Any, str]] = []
    for spec in defs:
        name = spec["name"]
        kind = spec["kind"]
        if kind == "bool":
            types[name] = Bool()
        elif kind == "char":
            types[name] = Char()
        elif kind == "int":
            types[name] = Int(spec["bits"])
        elif kind == "string":
            types[name] = String(spec["maxsize"])
        elif kind == "enum":
            types[name] = Enum(name, spec["values"])
        elif kind == "array":
            element = Array(None, spec["size"])
            types[name] = element
            deferred.append((element, "array", spec["element"]))
        elif kind == "struct":
            record = Struct(name, {})
            types[name] = record
            deferred.append((record, "struct", spec["fields"]))
        elif kind == "alias":
            link = Alias(name, None)
            types[name] = link
            deferred.append((link, "alias", spec["target"]))
        elif kind == "void":
            types[name] = Void()
        else:
            raise Exception("unknown type kind " + str(kind))
    for target, kind, payload in deferred:
        if kind == "array":
            target.element_type = types[payload]
        elif kind == "alias":
            target.type = types[payload]
        else:
            target.fields = {fname: types[tname] for fname, tname in payload}
            target.names = tuple(target.fields)
    return types


# --------------------------------------------------------------------------- #
# Modules
# --------------------------------------------------------------------------- #

class Parameter:
    """An Eywa parameter (or named result) of a function."""

    __slots__ = ("name", "type", "description")

    def __init__(self, name: str, type: Type, description: Optional[str] = None):
        self.name = name
        self.type = type
        self.description = description

    def __repr__(self):
        return "Parameter(%s)" % self.name


class Function:
    """An Eywa function that represents a model."""

    __slots__ = ("name", "description", "inputs", "result", "precondition")

    def __init__(self, name: str, description: str, inputs: List[Parameter],
                 result: Parameter, precondition=None):
        unique = {p.name for p in inputs}
        if len(unique) != len(inputs):
            raise Exception("duplicate parameter names")
        if result.name in unique:
            raise Exception("duplicate parameter names")
        self.name = name
        self.description = description
        self.inputs = list(inputs)
        self.result = result
        self.precondition = precondition

    @property
    def params(self):
        return self.inputs

    @property
    def requires(self):
        return self.precondition


FuncModule = Function


def parse_module(spec, types: Dict[str, Type]) -> Function:
    """Decode one module signature and compile its ``requires`` predicate."""
    params = [Parameter(pname, types[tname]) for pname, tname in spec["params"]]
    rname, rtname = spec["result"]
    result = Parameter(rname, types[rtname])
    context = {p.name: p.type for p in params}
    guard = spec.get("requires")
    precondition = None if guard is None else parse_expr(guard, types, context)
    return Function(spec["name"], "", params, result, precondition)


# --------------------------------------------------------------------------- #
# Expressions
# --------------------------------------------------------------------------- #

class Expr(object):
    """A simple expression class; subclasses evaluate against an assignment."""

    __slots__ = ("type",)

    def eval(self, assignment: Dict[str, Any]) -> Any:
        raise NotImplementedError(type(self).__name__)

    @staticmethod
    def decode(node, types: Dict[str, Type], context: Dict[str, Type]) -> "Expr":
        """Compile one JSON predicate node into a typed expression node."""
        form = node[0]
        if form == "var":
            name = node[1]
            return Var(context[name], name)
        if form == "const":
            declared = types[node[1]]
            return Const(declared, node[2])
        if form == "field":
            record = Expr._inner(node[1], types, context)
            fields = Type.inner(record.type).fields
            return Field(fields[node[2]], record, node[2])
        if form == "index":
            array = Expr._inner(node[1], types, context)
            element = Type.inner(array.type).element_type
            return Index(element, array, node[2])
        if form == "all":
            binding = node[1]
            array = Expr._inner(node[2], types, context)
            element = Type.inner(array.type).element_type
            scope = dict(context)
            scope[binding] = element
            body = parse_expr(node[3], types, scope)
            return Forall(Bool(), array, binding, body)
        if form == "match":
            text = Expr._inner(node[1], types, context)
            return Match(Bool(), text, regex.compile(node[2]))
        if form == "not":
            return Not(Bool(), parse_expr(node[1], types, context))
        if form in _BINOPS:
            return _BINOPS[form](node, types, context)
        raise Exception("unknown expression form " + str(form))

    @staticmethod
    def _inner(node, types, context) -> "Expr":
        return parse_expr(node, types, context)


def _binary_decode(node, types, context):
    left = parse_expr(node[1], types, context)
    right = parse_expr(node[2], types, context)
    return left, right


def _decode_compare(op):
    def build(node, types, context):
        left, right = _binary_decode(node, types, context)
        return Compare(Bool(), op, left, right)
    return build


def _decode_logical(op):
    def build(node, types, context):
        left, right = _binary_decode(node, types, context)
        return Logical(Bool(), op, left, right)
    return build


def _decode_arith(op):
    def build(node, types, context):
        left, right = _binary_decode(node, types, context)
        modulus = 1 << Type.inner(left.type).size
        return Arithmetic(left.type, op, left, right, modulus)
    return build


_BINOPS = {
    "eq": _decode_compare("eq"), "ne": _decode_compare("ne"),
    "lt": _decode_compare("lt"), "le": _decode_compare("le"),
    "gt": _decode_compare("gt"), "ge": _decode_compare("ge"),
    "and": _decode_logical("and"), "or": _decode_logical("or"),
    "implies": _decode_logical("implies"),
    "add": _decode_arith("add"), "sub": _decode_arith("sub"),
}


def parse_expr(node, types: Dict[str, Type], context: Dict[str, Type]) -> Expr:
    return Expr.decode(node, types, context)


class Var(Expr):
    """A lexical variable: a module input or the nearest enclosing binding."""

    __slots__ = ("type", "parameter_name")

    def __init__(self, type, parameter_name):
        self.type = type
        self.parameter_name = parameter_name

    def eval(self, assignment):
        return assignment[self.parameter_name]


class Const(Expr):
    """A typed constant; values obey the type's JSON representation."""

    __slots__ = ("type", "constant")

    def __init__(self, type, constant):
        self.type = type
        self.constant = constant

    def eval(self, assignment):
        return self.constant


class Field(Expr):
    """A struct field dereference."""

    __slots__ = ("type", "expr", "field")

    def __init__(self, type, expr: Expr, field: str):
        self.type = type
        self.expr = expr
        self.field = field

    def eval(self, assignment):
        return self.expr.eval(assignment)[self.field]


class Index(Expr):
    """A statically valid zero-based array index."""

    __slots__ = ("type", "expr", "index")

    def __init__(self, type, expr: Expr, index: int):
        self.type = type
        self.expr = expr
        self.index = index

    def eval(self, assignment):
        return self.expr.eval(assignment)[self.index]


class Not(Expr):
    """Boolean complement."""

    __slots__ = ("type", "expr")

    def __init__(self, type, expr: Expr):
        self.type = type
        self.expr = expr

    def eval(self, assignment):
        return not self.expr.eval(assignment)


class Match(Expr):
    """Full byte-string regular-language membership."""

    __slots__ = ("type", "expr", "pattern")

    def __init__(self, type, expr: Expr, pattern):
        self.type = type
        self.expr = expr
        self.pattern = pattern

    def eval(self, assignment):
        return self.pattern.matches(self.expr.eval(assignment))


class Forall(Expr):
    """Every element satisfies the predicate, binding that element."""

    __slots__ = ("type", "array_expr", "binding", "body")

    def __init__(self, type, array_expr: Expr, binding: str, body: "Expr"):
        self.type = type
        self.array_expr = array_expr
        self.binding = binding
        self.body = body

    def eval(self, assignment):
        elements = self.array_expr.eval(assignment)
        name = self.binding
        shadowed = name in assignment
        outer = assignment.get(name)
        body = self.body
        try:
            for element in elements:
                assignment[name] = element
                if not body.eval(assignment):
                    return False
        finally:
            if shadowed:
                assignment[name] = outer
            else:
                assignment.pop(name, None)
        return True


class Compare(Expr):
    """eq/ne compare deeply; lt/le/gt/ge compare unsigned integers."""

    __slots__ = ("type", "op", "left", "right")

    def __init__(self, type, op, left: Expr, right: Expr):
        self.type = type
        self.op = op
        self.left = left
        self.right = right

    def eval(self, assignment):
        left = self.left.eval(assignment)
        right = self.right.eval(assignment)
        op = self.op
        if op == "eq":
            return left == right
        if op == "ne":
            return left != right
        if op == "lt":
            return left < right
        if op == "le":
            return left <= right
        if op == "gt":
            return left > right
        return left >= right


class Logical(Expr):
    """Boolean and/or/implies with left-to-right short circuiting."""

    __slots__ = ("type", "op", "left", "right")

    def __init__(self, type, op, left: Expr, right: Expr):
        self.type = type
        self.op = op
        self.left = left
        self.right = right

    def eval(self, assignment):
        op = self.op
        if op == "and":
            return bool(self.left.eval(assignment)) and bool(self.right.eval(assignment))
        if op == "or":
            return bool(self.left.eval(assignment)) or bool(self.right.eval(assignment))
        return not self.left.eval(assignment) or bool(self.right.eval(assignment))


class Arithmetic(Expr):
    """add/sub use modulo 2^bits of the integer type."""

    __slots__ = ("type", "op", "left", "right", "modulus")

    def __init__(self, type, op, left: Expr, right: Expr, modulus: int):
        self.type = type
        self.op = op
        self.left = left
        self.right = right
        self.modulus = modulus

    def eval(self, assignment):
        left = self.left.eval(assignment)
        right = self.right.eval(assignment)
        if self.op == "add":
            return (left + right) % self.modulus
        return (left - right) % self.modulus
